params.command:
$ErrorActionPreference='Stop'
$repo='C:\Users\Xxkan\local-ai-workspaces\mhw-mods'
$expected=[ordered]@{
  'fix/heaven-secret-transport-hardening-20260929'='7e89cf354e4ba2207c33dfb07c1c1109d5978fae'
  'fix/issue-118-smb-hardening-20260929'='8472bea7d7890d2c37d92a5857eca82e8472dcf4'
  'fix/secret-channel-fail-closed-20260929'='5ccd44ad93b674e9ea093ca17595426b933e4671'
}
git -C $repo fetch origin --prune
$deleted=@();$skipped=@()
foreach($b in $expected.Keys){
 $line=(git -C $repo ls-remote origin "refs/heads/$b")
 if(-not $line){$skipped += [pscustomobject]@{branch=$b;reason='already-absent'};continue}
 $actual=(($line.Trim()) -split '\s+')[0]
 if($actual -ne $expected[$b]){$skipped += [pscustomobject]@{branch=$b;reason='tip-moved';expected=$expected[$b];actual=$actual};continue}
 git -C $repo push origin --delete $b
 if($LASTEXITCODE -ne 0){throw "delete failed $b"}
 $deleted += $b
}
git -C $repo fetch origin --prune
[pscustomobject]@{deleted=$deleted;skipped=$skipped;remaining=@(git -C $repo for-each-ref --format='%(refname:short) %(objectname)' refs/remotes/origin)}|ConvertTo-Json -Depth 5
